/* Leonida Trophy Atlas — Vice night: deep violet streets, neon pink and
   cyan. Pure CSS: no images, no web fonts, nothing fetched. Grade dots
   carry the medal colour; cards get a matching edge. */

:root {
  --night: #0c0716;
  --panel: #171029;
  --panel-2: #1e1436;
  --line: #2e2148;
  --ink: #f2ecff;
  --dim: #b3a6d4;
  --pink: #ff2e7e;
  --cyan: #2dd4ff;
  --gold: #ffd166;
  --silver: #c9d4e3;
  --bronze: #e0915a;
  --platinum: #7fe3ff;
  --good: #3ddc97;
  --radius: 14px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: radial-gradient(1100px 500px at 80% -10%, #2a1250 0%, transparent 60%),
    radial-gradient(900px 480px at -10% 10%, #3d0f3a 0%, transparent 55%),
    var(--night);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  min-height: 100vh;
}

.atlas-head {
  max-width: 1080px;
  margin: 0 auto;
  padding: 40px 20px 8px;
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--cyan);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

h1 {
  margin: 0 0 8px;
  font-size: clamp(32px, 5vw, 52px);
  line-height: 1.05;
  letter-spacing: -0.02em;
}

h1::after {
  content: "";
  display: block;
  width: 96px;
  height: 4px;
  margin-top: 12px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--pink), var(--cyan));
}

.lede { max-width: 680px; color: var(--dim); margin: 0 0 20px; }

.progress {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  padding: 14px 16px;
}

.progress-count { font-size: 18px; }
.progress-count strong { font-size: 26px; color: var(--gold); }

.progress-bar {
  height: 10px;
  margin: 10px 0;
  border-radius: 5px;
  background: #0a0614;
  overflow: hidden;
}

.progress-bar span {
  display: block;
